llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Telbivudine, a closely related thymidine nucleoside with the same thymine base and a similar sugar scaffold, has an absolute oral bioavailability of ~52% in subjects with normal renal function, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Zidovudine, another thymidine nucleoside reverse-transcriptase inhibitor, has an absolute oral bioavailability of 64% ± 21.3% after a 200 mg oral dose compared with intravenous administration in HIV-infected patients, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sorivudine, a uracil nucleoside analogue, has an absolute oral bioavailability of approximately 60%, providing additional evidence that this nucleoside scaffold is generally well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Even the lower-absorbed nucleoside analogue 882C87 has an absolute oral bioavailability of 21.1% in young volunteers, still meeting the F ≥ 20% threshold and supporting a high prediction for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is stavudine (d4T), a thymidine nucleoside analogue. Retrieved experimental evidence from closely related thymidine and uracil nucleosides consistently shows absolute oral bioavailability above 20%, with most values in the 50–70% range and the lowest analogue still at ~21%. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct stavudine-specific absolute bioavailability record is present in the retrieved evidence; the prediction relies on close nucleoside analogues.",
    "Some records report extent of absorption or unspecified bioavailability type rather than strictly absolute oral bioavailability, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

